//删除循环链串 cs 中下标为 idx 的字符（从 0 开始）
bool cs_delete(chainString &cs,int idx){
    if(cs==NULL || idx<0) return false;
    int i=0,j,len;
    chainString cs1=cs;
    do{
        len=strlen(cs1->data);
        if(i+len<=idx){
            i+=len;
            cs1=cs1->next;
        }else{
            for(j=idx-i;j<len;j++)
                cs1->data[j]=cs1->data[j+1]; //包括结尾的 '\0'
            if(len==1){
                if(cs1->next==cs1){
                    delete cs1;
                    cs=NULL;
                }else{
                    chainString pre=cs1->pre,nxt=cs1->next;
                    pre->next=nxt;
                    nxt->pre=pre;
                    if(cs1==cs) cs=nxt;
                    delete cs1;
                }
            }
            return true;
        }
    }while(cs1!=cs);
    return false;
}

