//带头结点的循环双向链表，按原位置奇偶拆成两个循环双向链表
void rcl_split(ChainList h, ChainList &h1, ChainList &h2){
    h1=new clNode;
    h2=new clNode;
    h1->next=h1;h1->pre=h1;
    h2->next=h2;h2->pre=h2;
    if(h==NULL) return;
    int pos=1;
    while(h->next!=h){
        ChainList q=h->next;
        h->next=q->next;
        q->next->pre=h;
        ChainList dst=(pos%2==1)?h1:h2;
        q->next=dst->next;
        q->pre=dst;
        dst->next->pre=q;
        dst->next=q;
        pos++;
    }
    h->pre=h;
}

