bool check(string exp){
    stack<char> ss;
    for(int i=0;i<exp.size();i++){
        if(exp[i]=='('||exp[i]=='['||exp[i]=='{') ss.push(exp[i]);
        else{
            if(exp[i]!=')'&&exp[i]!=']'&&exp[i]!='}') continue;
            if(ss.empty()) return false;
            char ch = ss.top();
            if(exp[i]==')'&&ch!='(' || exp[i]==']'&&ch!='[' || exp[i]=='}'&&ch!='{') return false;
            ss.pop();
        }
    }
    if(!ss.empty()) return false;
    return true;

}

