string convert(int num,int k){
    if(k<2 || k>36) return "";
    if(num==0) return "0";
    stack<char> ss;
    long long value=num;
    bool negative=value<0;
    if(negative) value=-value;
    while(value!=0){
        int r=value%k;
        char ch=(r<10)?'0'+r:'A'+r-10;
        ss.push(ch);
        value/=k;
    }
    string res=negative?"-":"";
    while(!ss.empty()){
        res+=ss.top();
        ss.pop();
    }
    return res;
}

