matrix mat_mul(matrix mat1, matrix mat2) {
    if (mat1.col != mat2.row) {
        cout << "矩阵不能相乘!" << endl;
        return matrix();
    }

    matrix mat(mat1.row, mat2.col); 

    for (int i = 0; i < mat1.row; i++)
        for (int j = 0; j < mat2.col; j++) {
            mat.a[i][j] = 0;
            for (int k = 0; k < mat1.col; k++)  
                mat.a[i][j] += mat1.a[i][k] * mat2.a[k][j];
        }

    return mat;
}

