    if(l>r) return;
    lazy[rt]=0;
    if(l==r){
        sum[rt]=a[l]; //到达叶结点
        return;
    }
    int mid = (l+r)>>1;
    build(a,rt<<1,l,mid);	//	构建左子树
    build(a,(rt<<1|1),mid+1,r);	//构建右子树
