//求树的括号表示btree中，结点cur的右兄弟结点，结果作为返回值
int r_bro(string btree,int cur){
    if(cur<0 || cur>=(int)btree.size()) return -1;
    if(btree[cur]=='(' || btree[cur]==')'){
        return -1;
    }
    int cnt=0;
    for(int i=cur+1;i<btree.size();i++){//cnt是一个计数器
        if(btree[i]=='(') cnt++;
        else if(btree[i]==')') cnt--;
        else if(btree[i]==',' && cnt==0)
            return i+1;
        if(cnt<0) break;
    }
    return -1;
}

